look.customCSS:
/* ───── 粉色日记 · 底：横线本、顶栏、底栏 ───── */
[data-wk="chat"]{background:#f6ecec url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%27390%27%20height%3D%2728%27%20viewBox%3D%270%200%20390%2028%27%3E%3Cpath%20d%3D%27M0%2027.5%20H390%27%20stroke%3D%27%23ecd3d6%27%20stroke-width%3D%271%27%2F%3E%3Cpath%20d%3D%27M30%200%20V28%27%20stroke%3D%27%23e9b8bf%27%20stroke-width%3D%271.2%27%20opacity%3D%27.7%27%2F%3E%3Ccircle%20cx%3D%2712%27%20cy%3D%2714%27%20r%3D%273.4%27%20fill%3D%27%23fff%27%20stroke%3D%27%23ecd3d6%27%20stroke-width%3D%271%27%2F%3E%3C%2Fsvg%3E") repeat !important;background-size:390px 28px !important}
[data-wk="body"]{background:transparent !important;padding-left:44px !important;padding-top:28px !important}
[data-wk="chathead"]{background:#fbf5f4 !important;border-bottom:none !important;box-shadow:none !important;position:relative !important;z-index:5 !important;overflow:visible !important}
[data-wk="chathead"]::after{content:"" !important;position:absolute !important;left:0 !important;right:0 !important;top:100% !important;height:16px !important;background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%2720%27%20height%3D%2716%27%20viewBox%3D%270%200%2020%2016%27%3E%3Cpath%20d%3D%27M0%200%20H20%20V4%20A5%205%200%200%201%2010%204%20A5%205%200%200%201%200%204Z%27%20fill%3D%27%23fbf5f4%27%2F%3E%3Cpath%20d%3D%27M0%204%20A5%205%200%200%200%2010%204%20A5%205%200%200%200%2020%204%27%20fill%3D%27none%27%20stroke%3D%27%23e9b8bf%27%20stroke-width%3D%271.4%27%2F%3E%3Ccircle%20cx%3D%275%27%20cy%3D%275%27%20r%3D%271.3%27%20fill%3D%27%23e9b8bf%27%2F%3E%3Ccircle%20cx%3D%2715%27%20cy%3D%275%27%20r%3D%271.3%27%20fill%3D%27%23e9b8bf%27%2F%3E%3C%2Fsvg%3E") repeat-x left top/20px 16px !important;pointer-events:none !important}
[data-wk="headink"]{color:#5e4245 !important}
[data-wk="headdim"]{color:#8a5a5f !important;opacity:.7 !important}
/* 顶栏收矮：小字那行藏掉，头像缩一号（上下留白不动，安全区照 app 的算） */
[data-wk="headname"] > div:nth-child(2){display:none !important}
[data-wk="chathead"] > button > [data-wk="avatar"],[data-wk="chathead"] [data-wk="avatar"]{width:30px !important;height:30px !important}
[data-wk="chatback"] svg{stroke:#8a5a5f !important}
[data-wk="chatmore"],[data-wk="sameroom"]{background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20100%20100%27%3E%3Cg%20transform%3D%27translate(8%2038)%20scale(1)%27%3E%3Cpath%20d%3D%27M12%2020%20C3%2013%201%208%204%204.5%20C7%201.5%2011%203%2012%206%20C13%203%2017%201.5%2020%204.5%20C23%208%2021%2013%2012%2020Z%27%20fill%3D%27%23e9b8bf%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%271.6%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fg%3E%3Cg%20transform%3D%27translate(38%2038)%20scale(1)%27%3E%3Cpath%20d%3D%27M12%2020%20C3%2013%201%208%204%204.5%20C7%201.5%2011%203%2012%206%20C13%203%2017%201.5%2020%204.5%20C23%208%2021%2013%2012%2020Z%27%20fill%3D%27%23f6e6c0%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%271.6%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fg%3E%3Cg%20transform%3D%27translate(68%2038)%20scale(1)%27%3E%3Cpath%20d%3D%27M12%2020%20C3%2013%201%208%204%204.5%20C7%201.5%2011%203%2012%206%20C13%203%2017%201.5%2020%204.5%20C23%208%2021%2013%2012%2020Z%27%20fill%3D%27%23bcd9cc%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%271.6%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E") center/26px 26px no-repeat !important;border:none !important;box-shadow:none !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="sameroom"]{background-image:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2024%27%3E%3Cpath%20d%3D%27M12%202%20L14.6%208.8%20L22%209.3%20L16.3%2014%20L18.2%2021.2%20L12%2017.2%20L5.8%2021.2%20L7.7%2014%20L2%209.3%20L9.4%208.8Z%27%20fill%3D%27%23f6e6c0%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%271.5%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fsvg%3E") !important;background-size:22px 22px !important}

[data-wk="composer"]{background:#fbf5f4 !important;border-top:1.5px solid #e9b8bf !important}
[data-wk="chatinput"]{background:#fff !important;border:1.5px solid #ecd3d6 !important;border-radius:6px !important;color:#5e4245 !important;background-image:linear-gradient(transparent 26px,#ecd3d6 26px,#ecd3d6 27px,transparent 27px) !important;background-size:100% 28px !important}
[data-wk="chatinput"]::placeholder{color:#8a5a5f !important;opacity:.5 !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;transition:transform .12s !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20100%20100%27%3E%3Ccircle%20cx%3D%2750%27%20cy%3D%2750%27%20r%3D%2734%27%20fill%3D%27%23fff%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%274%27%2F%3E%3Cpath%20d%3D%27M50%2034%20V66%20M34%2050%20H66%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%275%27%20stroke-linecap%3D%27round%27%2F%3E%3Cg%20transform%3D%27translate(70%2016)%20scale(1.1)%27%3E%3Cpath%20d%3D%27M12%2020%20C3%2013%201%208%204%204.5%20C7%201.5%2011%203%2012%206%20C13%203%2017%201.5%2020%204.5%20C23%208%2021%2013%2012%2020Z%27%20fill%3D%27%23e9b8bf%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%271.6%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E") center/contain no-repeat !important}
[data-wk="send"]{background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20100%20100%27%3E%3Cg%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%274%27%20stroke-linejoin%3D%27round%27%3E%3Crect%20x%3D%2714%27%20y%3D%2726%27%20width%3D%2772%27%20height%3D%2750%27%20rx%3D%276%27%20fill%3D%27%23fff%27%2F%3E%3Cpath%20d%3D%27M16%2030%20L50%2056%20L84%2030%27%20fill%3D%27none%27%2F%3E%3C%2Fg%3E%3Ccircle%20cx%3D%2750%27%20cy%3D%2758%27%20r%3D%2711%27%20fill%3D%27%23d9707e%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%272.5%27%2F%3E%3Cpath%20d%3D%27M50%2064%20C45%2060%2044%2057%2046%2055%20C48%2053%2050%2055%2050%2056%20C50%2055%2052%2053%2054%2055%20C56%2057%2055%2060%2050%2064Z%27%20fill%3D%27%23fff%27%2F%3E%3C%2Fsvg%3E") center/contain no-repeat !important}
[data-wk="chatreply"]{background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20100%20100%27%3E%3Cg%20transform%3D%27translate(18%208)%20scale(.64)%27%3E%3Cg%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%273%27%20stroke-linejoin%3D%27round%27%20fill%3D%27%23fff%27%3E%3Cpath%20d%3D%27M32%2048%20C24%2022%2026%204%2034%204%20C42%204%2044%2024%2042%2046%20Z%27%2F%3E%3Cpath%20d%3D%27M68%2048%20C76%2022%2074%204%2066%204%20C58%204%2056%2024%2058%2046%20Z%27%2F%3E%3Cellipse%20cx%3D%2750%27%20cy%3D%2766%27%20rx%3D%2732%27%20ry%3D%2726%27%2F%3E%3C%2Fg%3E%3Cpath%20d%3D%27M34%2042%20C30%2024%2031%2012%2034%2012%20C37%2012%2038%2026%2038%2040%20Z%20M66%2042%20C70%2024%2069%2012%2066%2012%20C63%2012%2062%2026%2062%2040%20Z%27%20fill%3D%27%23f2c4c8%27%2F%3E%3Ccircle%20cx%3D%2739%27%20cy%3D%2764%27%20r%3D%273.6%27%20fill%3D%27%235e4245%27%2F%3E%3Ccircle%20cx%3D%2761%27%20cy%3D%2764%27%20r%3D%273.6%27%20fill%3D%27%235e4245%27%2F%3E%3Cellipse%20cx%3D%2732%27%20cy%3D%2773%27%20rx%3D%276%27%20ry%3D%273.5%27%20fill%3D%27%23f2c4c8%27%2F%3E%3Cellipse%20cx%3D%2768%27%20cy%3D%2773%27%20rx%3D%276%27%20ry%3D%273.5%27%20fill%3D%27%23f2c4c8%27%2F%3E%3Cpath%20d%3D%27M46%2072%20q4%204%204%200%20q0%204%204%200%27%20fill%3D%27none%27%20stroke%3D%27%235e4245%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%2F%3E%3C%2Fg%3E%3Cpath%20d%3D%27M58%2052%20h28%20a8%208%200%200%201%208%208%20v12%20a8%208%200%200%201%20-8%208%20h-14%20l-8%208%20l1%20-8%20h-7%20a8%208%200%200%201%20-8%20-8%20v-12%20a8%208%200%200%201%208%20-8z%27%20fill%3D%27%23fff%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%273%27%2F%3E%3Ccircle%20cx%3D%2766%27%20cy%3D%2766%27%20r%3D%272.6%27%20fill%3D%27%238a5a5f%27%2F%3E%3Ccircle%20cx%3D%2774%27%20cy%3D%2766%27%20r%3D%272.6%27%20fill%3D%27%238a5a5f%27%2F%3E%3Ccircle%20cx%3D%2782%27%20cy%3D%2766%27%20r%3D%272.6%27%20fill%3D%27%238a5a5f%27%2F%3E%3C%2Fsvg%3E") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.86) !important}

/* 头像：拍立得小相框，兔耳探出来 */
[data-wk="avatar"]{position:relative !important;overflow:visible !important;border-radius:2px !important}
button[data-wk="avatar"]::before,span[data-wk="avatar"]:not([data-halo])::before{content:"" !important;position:absolute !important;width:58px !important;height:70px !important;left:calc(50% - 29px) !important;top:calc(50% - 42px) !important;z-index:2 !important;background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%20-10%20100%20130%27%3E%3Cg%20transform%3D%27translate(14%20-12)%20scale(.72)%27%3E%3Cg%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%275%27%20stroke-linejoin%3D%27round%27%20fill%3D%27%23fff%27%3E%3Cpath%20d%3D%27M32%2052%20C24%2022%2026%204%2034%204%20C42%204%2044%2024%2042%2050%20Z%27%2F%3E%3Cpath%20d%3D%27M68%2052%20C76%2022%2074%204%2066%204%20C58%204%2056%2024%2058%2050%20Z%27%2F%3E%3C%2Fg%3E%3Cpath%20d%3D%27M34%2044%20C30%2024%2031%2012%2034%2012%20C37%2012%2038%2026%2038%2042%20Z%20M66%2044%20C70%2024%2069%2012%2066%2012%20C63%2012%2062%2026%2062%2042%20Z%27%20fill%3D%27%23f2c4c8%27%2F%3E%3C%2Fg%3E%3Cpath%20fill-rule%3D%27evenodd%27%20d%3D%27M6%2022%20H94%20V116%20H6Z%20M14%2030%20V96%20H86%20V30Z%27%20fill%3D%27%23fff%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%272.5%27%20stroke-linejoin%3D%27round%27%2F%3E%3Cg%20transform%3D%27translate(68%20100)%20scale(.8)%27%3E%3Cpath%20d%3D%27M12%2020%20C3%2013%201%208%204%204.5%20C7%201.5%2011%203%2012%206%20C13%203%2017%201.5%2020%204.5%20C23%208%2021%2013%2012%2020Z%27%20fill%3D%27%23e9b8bf%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%271.6%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fg%3E%3Cg%20transform%3D%27translate(14%2014)%20rotate(-14)%20scale(.5)%27%3E%3Cpath%20d%3D%27M2%203%20L4%201%20L6%203%20L8%201%20L10%203%20L52%203%20L54%201%20L56%203%20L58%201%20L58%2019%20L56%2017%20L54%2019%20L52%2017%20L8%2017%20L6%2019%20L4%2017%20L2%2019Z%27%20fill%3D%27%23bcd9cc%27%20opacity%3D%27.75%27%2F%3E%3Cpath%20d%3D%27M14%203%20V17%20M28%203%20V17%20M42%203%20V17%27%20stroke%3D%27%23fff%27%20stroke-width%3D%273%27%20opacity%3D%27.45%27%2F%3E%3C%2Fg%3E%3C%2Fsvg%3E") center/contain no-repeat !important;pointer-events:none !important}
[data-wk="avatar"] *{border-radius:2px !important}

/* ───── 话：没有气泡，字落在横线上；你的竖线在右、他的在左；名字是荧光笔标签；已读跟在句尾 ───── */
[data-wk="row"] > div:has(> [data-wk="bubble"]){flex-direction:row !important;flex-wrap:wrap !important;align-items:baseline !important;column-gap:6px !important}
[data-wk="row"].justify-end > div:has(> [data-wk="bubble"]){justify-content:flex-end !important}
[data-wk="row"] > div > [data-wk="name"]{flex:0 0 100% !important;order:-2 !important}
[data-wk="row"].justify-end > div > [data-wk="name"]{text-align:right !important}
[data-wk="row"] > div > [data-wk="meta"]{flex:0 0 100% !important;order:1 !important;justify-content:flex-start !important}
[data-wk="row"].justify-end > div > [data-wk="meta"]{justify-content:flex-end !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
/* 一串最后是表情包、卡片：已读写在它底下（v89.457 起的 cardmeta 挂点） */
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#8a5a5f !important;opacity:.65 !important;line-height:28px !important;padding:0 6px 0 60px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:0 60px 0 6px !important}
[data-wk="cardmeta"]::before{content:"" !important;display:inline-block !important;width:9px !important;height:8px !important;margin-right:4px !important;background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2022%27%3E%3Cpath%20d%3D%27M12%2020%20C3%2013%201%208%204%204.5%20C7%201.5%2011%203%2012%206%20C13%203%2017%201.5%2020%204.5%20C23%208%2021%2013%2012%2020Z%27%20fill%3D%27%23bcd9cc%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%271.6%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fsvg%3E") center/contain no-repeat !important}
[data-wk="name"]{display:block !important;color:#8a5a5f !important;font-style:italic !important;letter-spacing:.08em !important;line-height:28px !important;height:28px !important;margin:0 !important;padding:0 !important}
[data-wk="name"]::first-line{background:linear-gradient(transparent 22%,rgba(188,217,204,.8) 22%,rgba(188,217,204,.8) 85%,transparent 85%) !important}
[data-wk="row"].justify-end > div > [data-wk="name"]::first-line{background:linear-gradient(transparent 22%,rgba(233,184,191,.85) 22%,rgba(233,184,191,.85) 85%,transparent 85%) !important}
[data-wk="name"]::after{content:" 说：" !important}
[data-wk="bubble"][data-kind="text"]{background:transparent !important;box-shadow:none !important;border:none !important;border-radius:0 !important;transform:none !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;line-height:28px !important;padding:0 12px !important;margin:0 !important;color:#5e4245 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{border-left:3px solid #e9b8bf !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{border-right:3px solid #e9b8bf !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="meta"]{color:#8a5a5f !important;opacity:.65 !important;font-size:10.5px !important;line-height:28px !important;margin:0 !important}
[data-wk="meta"]::before{content:"" !important;display:inline-block !important;width:9px !important;height:8px !important;margin-right:4px !important;background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2022%27%3E%3Cpath%20d%3D%27M12%2020%20C3%2013%201%208%204%204.5%20C7%201.5%2011%203%2012%206%20C13%203%2017%201.5%2020%204.5%20C23%208%2021%2013%2012%2020Z%27%20fill%3D%27%23bcd9cc%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%271.6%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fsvg%3E") center/contain no-repeat !important}

/* 时间：写进左边页边那一栏，跟活页孔排在一起 */
[data-wk="msg"]{position:relative !important}
[data-wk="time"]{position:absolute !important;left:-40px !important;top:0 !important;width:30px !important;margin:0 !important;text-align:center !important;z-index:1 !important}
[data-wk="time"] > span{display:block !important;background:#f6e6c0 !important;color:#8a5a5f !important;font-size:9px !important;line-height:12px !important;padding:3px 1px !important;border-radius:2px !important;transform:rotate(-4deg) !important;word-break:break-all !important;box-shadow:0 1px 0 rgba(138,90,95,.15) !important}
[data-wk="msg"]{padding:0 !important;margin:0 0 28px !important}
[data-wk="msg"] + [data-wk="msg"]{margin-top:0 !important}
[data-wk="body"] > *{margin-top:0 !important}

/* 正在输入：三颗小爱心 */
