/* 引用：一张夹在输入框上的小纸条，回形针别着 */
[data-wk="quotedraft"]{background:#fff !important;border:1.5px solid #ecd3d6 !important;border-left:3px solid #e9b8bf !important;border-radius:2px !important;position:relative !important;overflow:visible !important;transform:rotate(-.5deg) !important}
[data-wk="quotedraft"]::before{content:"" !important;position:absolute !important;top:-12px !important;left:14px !important;width:12px !important;height:30px !important;background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2016%2040%27%3E%3Cpath%20d%3D%27M5%2036%20V8%20a4%204%200%200%201%208%200%20V32%20a6%206%200%200%201%20-12%200%20V12%27%20fill%3D%27none%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%272%27%20stroke-linecap%3D%27round%27%2F%3E%3C%2Fsvg%3E") center/contain no-repeat !important}
[data-wk="quotedraft"] *{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="quotedraft"] > *{padding-left:20px !important}
[data-wk="quoteicon"]{color:#e9b8bf !important}
[data-wk="quotetext"]{color:#8a5a5f !important;font-style:italic !important}
[data-wk="quoteclear"]{color:#8a5a5f !important}

/* 拆开红包那一页：一张粉色信纸 */
[data-wk="rpenvelope"][data-stage="open"]{background:#fbf5f4 url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%27390%27%20height%3D%2728%27%20viewBox%3D%270%200%20390%2028%27%3E%3Cpath%20d%3D%27M0%2027.5%20H390%27%20stroke%3D%27%23ecd3d6%27%20stroke-width%3D%271%27%2F%3E%3Cpath%20d%3D%27M30%200%20V28%27%20stroke%3D%27%23e9b8bf%27%20stroke-width%3D%271.2%27%20opacity%3D%27.7%27%2F%3E%3Ccircle%20cx%3D%2712%27%20cy%3D%2714%27%20r%3D%273.4%27%20fill%3D%27%23fff%27%20stroke%3D%27%23ecd3d6%27%20stroke-width%3D%271%27%2F%3E%3C%2Fsvg%3E") repeat !important;background-size:390px 28px !important;border:1.5px solid #e9b8bf !important;border-radius:4px !important;box-shadow:0 14px 34px rgba(94,66,69,.25) !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rparc"]{background:linear-gradient(175deg,#efb6c0,#d9808f) !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rpfrom"]{color:#5e4245 !important;font-style:italic !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rpwish"]{color:#8a5a5f !important}
[data-wk="rpavatar"]{border-radius:2px !important;box-shadow:0 0 0 4px #fff,0 0 0 5.5px #e9b8bf !important;transform:rotate(-3deg) !important}
[data-wk="rpavatar"] *{border-radius:2px !important}
[data-wk="rpamount"]{color:#d9707e !important;background:linear-gradient(transparent 60%,rgba(246,230,192,.9) 60%) !important;padding:0 6px !important}
[data-wk="rpstatus"]{color:#8a5a5f !important;font-style:italic !important}
[data-wk="rpclose"]{background:#fff url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%2024%2022%27%3E%3Cpath%20d%3D%27M12%2020%20C3%2013%201%208%204%204.5%20C7%201.5%2011%203%2012%206%20C13%203%2017%201.5%2020%204.5%20C23%208%2021%2013%2012%2020Z%27%20fill%3D%27%23e9b8bf%27%20stroke%3D%27%238a5a5f%27%20stroke-width%3D%271.6%27%20stroke-linejoin%3D%27round%27%2F%3E%3C%2Fsvg%3E") center/0 0 no-repeat !important;border:1.5px solid #e9b8bf !important;color:#8a5a5f !important}
[data-wk="rpenvelope"][data-stage="closed"]{border-radius:6px !important;border:2px solid #fff !important}
[data-wk="rpenvelope"][data-stage="closed"] [data-wk="rpwish"],[data-wk="rpenvelope"][data-stage="closed"] [data-wk="rpfrom"]{color:#fff !important}

/* 状态卡页头：名字＋「的日记」一行写完 */
[data-wk="statehead"] > div > div:first-child{white-space:nowrap !important;font-size:20px !important;overflow:hidden !important;text-overflow:ellipsis !important}
[data-wk="statehead"]{position:relative !important}
[data-wk="statehead"] > [data-wk="avatar"]{width:54px !important;height:54px !important;flex:0 0 54px !important}
[data-wk="statehead"] > button{position:absolute !important;right:84px !important;top:14px !important;width:26px !important;height:26px !important}
[data-wk="statehead"] > div > div:first-child::after{display:block !important;font-size:11px !important;line-height:1.2 !important;letter-spacing:.2em !important}
[data-wk="statehead"]{padding-right:118px !important}

/* 顶栏＝日记本封面：粉色布面，中间缝一块白色布标签写名字 */
[data-wk="chathead"]{background:radial-gradient(circle,rgba(255,255,255,.75) 1.6px,transparent 2.2px) 0 0/14px 14px,radial-gradient(circle,rgba(255,255,255,.75) 1.6px,transparent 2.2px) 7px 7px/14px 14px,linear-gradient(180deg,#f2b3c0,#f6c8d1) !important}
[data-wk="chathead"]::after{background:url("data:image/svg+xml;utf8,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%2720%27%20height%3D%2716%27%20viewBox%3D%270%200%2020%2016%27%3E%3Cpath%20d%3D%27M0%200%20H20%20V4%20A5%205%200%200%201%2010%204%20A5%205%200%200%201%200%204Z%27%20fill%3D%27%23f6c8d1%27%2F%3E%3Cpath%20d%3D%27M0%204%20A5%205%200%200%200%2010%204%20A5%205%200%200%200%2020%204%27%20fill%3D%27none%27%20stroke%3D%27%23fff%27%20stroke-width%3D%271.4%27%2F%3E%3C%2Fsvg%3E") repeat-x left top/20px 16px !important}
[data-wk="chathead"] [data-wk="headname"]{background:#fffaf7 !important;border:1.5px solid #8a5a5f !important;box-shadow:0 0 0 3px #fffaf7,0 0 0 4.5px #e9b8bf,2px 3px 0 4px rgba(94,66,69,.18) !important;border-radius:3px !important;padding:2px 10px !important;transform:rotate(-1.5deg) !important;flex:0 1 auto !important;max-width:none !important;min-width:0 !important}
[data-wk="chathead"] [data-wk="headink"]{color:#5e4245 !important;font-style:italic !important}
[data-wk="chathead"] [data-wk="headink"] > span:first-child{overflow:visible !important;text-overflow:clip !important}
[data-wk="chathead"] [data-wk="chatback"] svg{stroke:#fff !important}
[data-wk="chathead"] [data-wk="headdim"]{color:#8a5a5f !important}
[data-wk="statehistbtn"][data-part="more"]{border:none !important;border-top:1.5px solid #ecd3d6 !important;border-radius:0 !important}

/* 页头改成上下排：先一张拍立得，下面写名字和心情，右边只给丝带留位置 */
[data-wk="statehead"]{display:block !important;padding:16px 84px 12px 40px !important}
[data-wk="statehead"] > [data-wk="avatar"]{display:block !important;width:56px !important;height:56px !important;margin:0 0 8px !important}
[data-wk="statehead"] > [data-wk="avatar"] *{width:56px !important;height:56px !important}
[data-wk="statehead"] > div{display:block !important;width:auto !important;min-width:0 !important}
[data-wk="statehead"] > div > div{white-space:normal !important;overflow:visible !important}
[data-wk="statehead"] > div > div:first-child{white-space:nowrap !important;overflow:hidden !important;text-overflow:ellipsis !important;font-size:20px !important}
[data-wk="statehead"] > div > div:first-child::after{display:inline !important;font-size:12px !important;letter-spacing:.1em !important}
[data-wk="statehead"] > button{position:absolute !important;left:110px !important;right:auto !important;top:18px !important;width:28px !important;height:28px !important}
[data-wk="statehead"] button[aria-label="关掉"]{position:absolute !important;left:116px !important;top:30px !important;right:auto !important}
